71	// auditDiffReport 用给定规则与检查记录通过真实 audit 命令落盘一份报告并解码返回。
72	func auditDiffReport(t *testing.T, bin, work, store, name string, artifact cliWireArtifact, rules []cliWireRule, checks []cliWireCheck) contractsentinel.Report {
