233		// 超时→发现缺陷：只是检查状态变化，不能记为新缺陷；新侧确有缺陷记录。
234		m := diffEntry(t, d, "m-timeout-to-defect")
235		if m.Before.Rule.Status != contractsentinel.StatusTimeout || m.Before.Rule.Note != "超过 60s 截止时间" {
236			t.Errorf("m before = %+v", m.Before.Rule)
237		}
238		if m.After.Rule.Status != contractsentinel.StatusDefect || m.After.Finding == nil ||
239			m.After.Finding.Evidence != defectNote || m.After.Finding.Version != "7" || m.After.Finding.ArtifactHash != hash {
240			t.Errorf("m after must carry the real defect finding: before=%+v after=%+v", m.Before, m.After)
241		}
242		if m.Before.Finding != nil {
243			t.Errorf("timeout side must not carry a finding: %+v", m.Before.Finding)
244		}
245	
246		// 发现缺陷→超时：只是检查状态变化，不能记为已消除；旧侧缺陷记录仍在。
247		n := diffEntry(t, d, "n-defect-to-timeout")
248		if n.Before.Rule.Status != contractsentinel.StatusDefect || n.Before.Finding == nil ||
249			n.Before.Finding.Evidence != "超时前发现的反例" || n.Before.Finding.Version != "8" {
250			t.Errorf("n before must keep its defect finding: %+v", n.Before)
251		}
252		if n.After.Rule.Status != contractsentinel.StatusTimeout || n.After.Rule.Note != "复跑超过 60s 截止时间" {
253			t.Errorf("n after = %+v", n.After.Rule)
254		}
255		if n.After.Finding != nil {
256			t.Errorf("timeout side must not carry a finding: %+v", n.After.Finding)
257		}
