224	// 分类边界：两侧都发现缺陷且说明不同，但规则版本已变化时仍归为“规则变化”，
225	// 不同时计为说明变化；两侧各自保留自己的反例证据与版本绑定。
226	func TestDiffDefectNoteChangeWithVersionBumpIsRuleChange(t *testing.T) {
227		dir := t.TempDir()
228		artifact := sampleArtifact()
229		hash := ArtifactHash(artifact)
230		before := saveCheckReport(t, dir, artifact, defectNoteRules(),
231			[]CheckRecord{defectCheck(hash, defectNoteBefore)})
232		afterRules := []Rule{{ID: "reentrancy-guard", Kind: "static", Severity: "high", Invariant: "no-reentrant-withdraw", Version: "1.4.3"}}
233		after := saveCheckReport(t, dir, artifact, afterRules,
234			[]CheckRecord{{ArtifactHash: hash, RuleID: "reentrancy-guard", Version: "1.4.3", Status: StatusDefect, Note: defectNoteAfter}})
