144		for side, f := range map[string]*contractsentinel.ReportFinding{"before": bf, "after": af} {
145			if f.ArtifactHash != hash || f.RuleID != rule.ID || f.Version != rule.Version {
146				t.Errorf("%s finding binding = %+v, want hash=%q rule=%q version=%q",
