189				if len(reloaded.Rules) != 1 || len(reloaded.Findings) != 1 {
190					t.Fatalf("reloaded report shape = %+v", reloaded)
191				}
192				if reloaded.Rules[0].Note != tc.notice || reloaded.Findings[0].Evidence != tc.notice {
193					t.Errorf("readback lost its counterexample: note=%q evidence=%q, want %q",
194						reloaded.Rules[0].Note, reloaded.Findings[0].Evidence, tc.notice)
195				}
196				if reloaded.Findings[0].ArtifactHash != hash || reloaded.Findings[0].RuleID != rule.ID ||
197					reloaded.Findings[0].Version != rule.Version {
198					t.Errorf("readback finding binding = %+v", reloaded.Findings[0])
199				}
