204	// TestCLIDiffDefectNoteTrailingSpaceIsNoteChange 在进程边界上固定说明按原文
205	// 比较的边界：仅增加一个尾随空格也属于说明变化，两侧文字逐字保留。
206	func TestCLIDiffDefectNoteTrailingSpaceIsNoteChange(t *testing.T) {
207		bin := auditBinary(t)
208		work := t.TempDir()
209		store := filepath.Join(work, "reports")
210		artifact := mixedCheckArtifact()
211		hash := mixedArtifactHash(t)
212		rule := cliDefectNoteRule()
213		base := "反例：重入路径仍可达\n  第二行证据"
214	
215		before := auditDiffReport(t, bin, work, store, "before.json", artifact,
216			[]cliWireRule{rule},
217			[]cliWireCheck{{ArtifactHash: hash, RuleID: rule.ID, Version: rule.Version,
218				Status: contractsentinel.StatusDefect, Note: base}})
219		after := auditDiffReport(t, bin, work, store, "after.json", artifact,
220			[]cliWireRule{rule},
221			[]cliWireCheck{{ArtifactHash: hash, RuleID: rule.ID, Version: rule.Version,
222				Status: contractsentinel.StatusDefect, Note: base + " "}})
223	
224		stdout, stderr, code := runCLIDiff(t, bin, store, before.ReportID, after.ReportID)
225		if code != 0 {
226			t.Fatalf("diff must succeed, exit=%d stderr=%s", code, stderr)
227		}
228		d := decodeDiff(t, stdout)
229		if len(d.Results) != 1 || d.Results[0].Change != contractsentinel.ChangeNoteChanged {
230			t.Fatalf("a trailing space is a note change: %+v", d.Results)
231		}
232		if d.Summary.NoteChanges != 1 || d.Summary.BeforeDefects != 1 || d.Summary.AfterDefects != 1 {
233			t.Errorf("summary = %+v, want noteChanges=1 defects=1/1", d.Summary)
234		}
235		entry := d.Results[0]
236		if entry.Before.Rule.Note != base || entry.Before.Finding == nil || entry.Before.Finding.Evidence != base {
237			t.Errorf("before side must keep the note verbatim without trailing space: %+v", entry.Before)
238		}
239		if entry.After.Rule.Note != base+" " || entry.After.Finding == nil || entry.After.Finding.Evidence != base+" " {
240			t.Errorf("after side must keep the trailing space verbatim: %+v", entry.After)
241		}
242		// 字节层面：带尾随空格的新证据逐字出现在输出里（JSON 转义后空格仍在）。
243		escaped := strings.ReplaceAll(base+" ", "\n", `\n`)
244		if !strings.Contains(stdout, escaped) {
245			t.Errorf("diff output must preserve the trailing space verbatim:\n%s", stdout)
246		}
247	}
248	
249	// TestCLIDiffDefectNoteChangeWithVersionBumpIsRuleChange 固定分类边界：两侧
250	// 都发现缺陷且说明不同，但规则版本已变化时仍归为“规则变化”，不计说明变化。
251	func TestCLIDiffDefectNoteChangeWithVersionBumpIsRuleChange(t *testing.T) {
252		bin := auditBinary(t)
253		work := t.TempDir()
254		store := filepath.Join(work, "reports")
255		artifact := mixedCheckArtifact()
256		hash := mixedArtifactHash(t)
257		beforeRule := cliDefectNoteRule()
258		afterRule := cliDefectNoteRule()
259		afterRule.Version = "1.4.3"
260	
261		before := auditDiffReport(t, bin, work, store, "before.json", artifact,
262			[]cliWireRule{beforeRule},
263			[]cliWireCheck{{ArtifactHash: hash, RuleID: beforeRule.ID, Version: beforeRule.Version,
264				Status: contractsentinel.StatusDefect, Note: cliDefectNoteBefore}})
265		after := auditDiffReport(t, bin, work, store, "after.json", artifact,
266			[]cliWireRule{afterRule},
267			[]cliWireCheck{{ArtifactHash: hash, RuleID: afterRule.ID, Version: afterRule.Version,
268				Status: contractsentinel.StatusDefect, Note: cliDefectNoteAfter}})
269	
270		stdout, stderr, code := runCLIDiff(t, bin, store, before.ReportID, after.ReportID)
271		if code != 0 {
272			t.Fatalf("diff must succeed, exit=%d stderr=%s", code, stderr)
273		}
274		d := decodeDiff(t, stdout)
275		if len(d.Results) != 1 || d.Results[0].Change != contractsentinel.ChangeRuleChanged {
276			t.Fatalf("version bump must stay 规则变化: %+v", d.Results)
277		}
278		s := d.Summary
279		if s.ChangedRules != 1 || s.NoteChanges != 0 {
280			t.Errorf("changedRules/noteChanges = %d/%d, want 1/0", s.ChangedRules, s.NoteChanges)
281		}
282		if s.NewDefects != 0 || s.ResolvedDefects != 0 || s.StatusChanges != 0 {
283			t.Errorf("rule change must not count as defect or status change: %+v", s)
284		}
285		if s.BeforeDefects != 1 || s.AfterDefects != 1 {
286			t.Errorf("defect totals = %d/%d, want 1/1", s.BeforeDefects, s.AfterDefects)
287		}
288		entry := d.Results[0]
289		if entry.Before.Finding == nil || entry.Before.Finding.Evidence != cliDefectNoteBefore ||
290			entry.Before.Finding.Version != "1.4.2" {
291			t.Errorf("before side must keep the old evidence at the old version: %+v", entry.Before.Finding)
292		}
293		if entry.After.Finding == nil || entry.After.Finding.Evidence != cliDefectNoteAfter ||
294			entry.After.Finding.Version != "1.4.3" {
295			t.Errorf("after side must keep the new evidence at the new version: %+v", entry.After.Finding)
296		}
297	}
